817	template <int CN, int CM, bool EXTRA>
818	__device__ __forceinline__ PfTile pf_work(
819	        int work, int tiles_m, int hkv, int rep,
820	        const int* __restrict__ cu_q, const int* __restrict__ cu_k, const int* __restrict__ seqused_k,
821	        int causal, int win_l, int win_r, float scale,
822	        const float* __restrict__ q_descale, const float* __restrict__ k_descale,
823	        const float* __restrict__ v_descale, int ds_b, int ds_h) {
824	    PfTile t; t.valid = false;
825	    const int hb = tiles_m * hkv;
826	    const int bi = work / hb;
827	    const int rem = work - bi * hb;
828	    t.hk = rem / tiles_m;
829	    const int m_block = (tiles_m - 1) - (rem - t.hk * tiles_m);   // LPT: largest causal tile first
830	    t.q0 = cu_q[bi];
831	    t.seqlen_q = cu_q[bi + 1] - t.q0;
832	    t.seqlen_k = seqused_k ? seqused_k[bi] : (cu_k[bi + 1] - cu_k[bi]);
833	    t.Mrows = t.seqlen_q * rep;
834	    t.row0 = m_block * CM;
835	    if (t.row0 >= t.Mrows || t.seqlen_k <= 0) return t;            // padded m_block / empty seq
836	    t.delta = t.seqlen_k - t.seqlen_q;
837	    const long ds_idx = (long)bi * ds_b + (long)t.hk * ds_h;
838	    const float qd = q_descale ? q_descale[ds_idx] : 1.f;
839	    const float kd = k_descale ? k_descale[ds_idx] : 1.f;
840	    t.vd = v_descale ? v_descale[ds_idx] : 1.f;
841	    t.sc_eff = scale * qd * kd;
842	    t.s2 = t.sc_eff * float(M_LOG2E);
843	    const int top = (t.row0 + CM - 1 < t.Mrows - 1) ? (t.row0 + CM - 1) : (t.Mrows - 1);
844	    const int qabs_max = (top / rep) + t.delta;
845	    int n_max = causal ? ((qabs_max + 1 + CN - 1) / CN) : ((t.seqlen_k + CN - 1) / CN);
846	    int n_beg = 0;
847	    if constexpr (EXTRA) {
848	        if (win_l >= 0) { int lo = (t.row0 / rep) + t.delta - win_l; if (lo > 0) n_beg = lo / CN; }
849	        if (!causal && win_r >= 0) { int tt = (qabs_max + win_r) / CN + 1; if (tt < n_max) n_max = tt; }
850	    }
851	    if (n_beg >= n_max) return t;                                  // fully masked
852	    t.n_lo = n_beg; t.n_cnt = n_max - n_beg;
853	    t.valid = true;
854	    return t;
855	}
