2400	} // namespace pf
2401	
2402	// ======================================================================================
2403	// FAST PATH 2: decode (q_len small), flash-decoding with split-KV.
2404	//
2405	// Memory-bound regime (the QK/PV are tiny GEMVs; the bottleneck is streaming the paged KV cache).
2406	// One WARP per (batch, kv_head, kv_split) work-item; 128-thread blocks pack 4 independent warps.
2407	// A warp processes ALL packed-GQA rows (M = q_len * rep) of its (b,hk) over its key slice, with
2408	// lane L owning the contiguous head-dim chunk [L*per, L*per+per) so K/V loads are 256 B coalesced and
2409	// the QK dot is a single warp reduction. Each warp writes a NORMALIZED partial (O_s, lse_s) to scratch;
2410	// `combine_kernel` does the across-split flash reduction. Matches the scalar fallback semantics
2411	// (qk_scale = scale*qd*kd, softcap after scale, causal + sliding-window, q_abs = klen - sq + qpos).
2412	namespace dec {
2413	constexpr int WARP = 32, WARPS_PER_BLOCK = 4, DEC_THREADS = WARP * WARPS_PER_BLOCK;
2414	
2415	__device__ __forceinline__ float wreduce_sum(float v) {
2416	#pragma unroll
2417	    for (int o = 16; o > 0; o >>= 1) v += __shfl_xor_sync(0xffffffffu, v, o);
2418	    return v;
2419	}
2420	
2421	// One warp = one (b, hk, split). MAXM bounds the packed-GQA rows; per/perv = HD/32, HDV/32 dims/lane.
2422	template <typename TIn, typename TOut, int HD, int HDV, int MAXM>
2423	__global__ void decode_kernel(
2424	        const TIn* __restrict__ Q, const TIn* __restrict__ K, const TIn* __restrict__ V,
2425	        float* __restrict__ Opart, float* __restrict__ LSEpart,
2426	        const int* __restrict__ cu_q, const int* __restrict__ cu_k, const int* __restrict__ seqused_k,
2427	        const int* __restrict__ page_table,
2428	        const float* __restrict__ q_descale, const float* __restrict__ k_descale, const float* __restrict__ v_descale,
2429	        int ds_b, int ds_h,
2430	        long q_row, long q_head, long k_row, long k_head, long v_row, long v_head,
2431	        int batch, int hq, int hkv, int rep, int total_q, int block_size, int page_stride,
2432	        int num_splits, float scale, float softcap, int win_l, int win_r, int causal) {
2433	    constexpr int per = HD / 32, perv = HDV / 32;
2434	    const int witem = blockIdx.x * WARPS_PER_BLOCK + (threadIdx.x >> 5);
2435	    const int lane = threadIdx.x & 31;
2436	    if (witem >= num_splits * hkv * batch) return;
2437	    // work-item -> (b, hk, split)
2438	    const int split = witem % num_splits;
2439	    int tmp = witem / num_splits;
2440	    const int hk = tmp % hkv;
2441	    const int b = tmp / hkv;
2442	    // b is bounded by the launch (grid sized to batch); guard:
2443	    const int q0 = cu_q[b];
2444	    const int sq = cu_q[b + 1] - q0;
2445	    if (sq <= 0) return;
2446	    const int klen = seqused_k ? seqused_k[b] : (cu_k[b + 1] - cu_k[b]);
2447	    const int M = sq * rep;
2448	
2449	    const long ds_idx = (long)b * ds_b + (long)hk * ds_h;
2450	    const float qd = q_descale ? q_descale[ds_idx] : 1.f;
2451	    const float kd = k_descale ? k_descale[ds_idx] : 1.f;
2452	    const float vd = v_descale ? v_descale[ds_idx] : 1.f;
2453	    const float qk_scale = scale * qd * kd;
2454	
2455	    // split's key range
2456	    const int span = (klen + num_splits - 1) / num_splits;
2457	    const int jlo = split * span;
2458	    const int jhi = min(jlo + span, klen);
2459	
2460	    float qreg[MAXM][per];
2461	    float acc[MAXM][perv];
2462	    float mrow[MAXM], lrow[MAXM];
2463	    int qabs[MAXM];
2464	#pragma unroll
2465	    for (int mi = 0; mi < MAXM; ++mi) {
2466	        if (mi >= M) break;
2467	        const int qpos = mi / rep, r = mi % rep;
2468	        const int head = hk * rep + r;
2469	        const TIn* qp = Q + (long)(q0 + qpos) * q_row + (long)head * q_head;
2470	#pragma unroll
2471	        for (int e = 0; e < per; ++e) qreg[mi][e] = to_float<TIn>(qp[lane * per + e]);
2472	#pragma unroll
2473	        for (int e = 0; e < perv; ++e) acc[mi][e] = 0.f;
2474	        mrow[mi] = -INFINITY; lrow[mi] = 0.f;
2475	        qabs[mi] = klen - sq + qpos;
2476	    }
2477	
2478	    // Software-pipelined K/V load: issue key (j+1)'s gmem loads (including the dependent page_table
2479	    // lookup) while computing on key j, so the load latency overlaps the (short) softmax compute.
2480	    auto load_key = [&](int j, float* kx, float* vx) {
2481	        long krow;
2482	        if (page_table) { int blk = page_table[(long)b * page_stride + j / block_size]; krow = (long)blk * block_size + (j % block_size); }
2483	        else            { krow = (long)cu_k[b] + j; }
2484	        const TIn* kp = K + krow * k_row + (long)hk * k_head;
2485	        const TIn* vp = V + krow * v_row + (long)hk * v_head;
2486	#pragma unroll
2487	        for (int e = 0; e < per; ++e)  kx[e] = to_float<TIn>(kp[lane * per + e]);
2488	#pragma unroll
2489	        for (int e = 0; e < perv; ++e) vx[e] = to_float<TIn>(vp[lane * perv + e]);
2490	    };
2491	    float kxA[per], vxA[perv], kxB[per], vxB[perv];
2492	    if (jlo < jhi) load_key(jlo, kxA, vxA);
2493	    for (int j = jlo; j < jhi; ++j) {
2494	        const bool A = ((j - jlo) & 1) == 0;
2495	        float* kx = A ? kxA : kxB; float* vx = A ? vxA : vxB;
2496	        if (j + 1 < jhi) load_key(j + 1, A ? kxB : kxA, A ? vxB : vxA);   // prefetch next
2497	#pragma unroll
2498	        for (int mi = 0; mi < MAXM; ++mi) {
2499	            if (mi >= M) break;
2500	            const int qa = qabs[mi];
2501	            bool masked = (causal && j > qa) || (win_l >= 0 && j < qa - win_l) || (win_r >= 0 && j > qa + win_r);
2502	            float dot = 0.f;
2503	#pragma unroll
2504	            for (int e = 0; e < per; ++e) dot += qreg[mi][e] * kx[e];
2505	            float s = wreduce_sum(dot) * qk_scale;
2506	            if (softcap > 0.f) s = softcap * tanhf(s / softcap);
2507	            if (masked) continue;
2508	            float mnew = fmaxf(mrow[mi], s);
2509	            float corr = __expf(mrow[mi] - mnew), p = __expf(s - mnew);
2510	            lrow[mi] = lrow[mi] * corr + p;
2511	#pragma unroll
2512	            for (int e = 0; e < perv; ++e) acc[mi][e] = acc[mi][e] * corr + p * (vx[e] * vd);
2513	            mrow[mi] = mnew;
2514	        }
2515	    }
2516	
2517	#pragma unroll
2518	    for (int mi = 0; mi < MAXM; ++mi) {
2519	        if (mi >= M) break;
2520	        const int qpos = mi / rep, r = mi % rep;
2521	        const int head = hk * rep + r, qidx = q0 + qpos;
2522	        const float inv = lrow[mi] > 0.f ? 1.f / lrow[mi] : 0.f;
2523	        float* op = Opart + (((long)split * total_q + qidx) * hq + head) * HDV;
2524	#pragma unroll
2525	        for (int e = 0; e < perv; ++e) op[lane * perv + e] = acc[mi][e] * inv;
2526	        if (lane == 0)
2527	            LSEpart[((long)split * hq + head) * total_q + qidx] =
2528	                (lrow[mi] > 0.f) ? (mrow[mi] + __logf(lrow[mi])) : -INFINITY;
2529	    }
2530	}
2531	
2532	// Flash-combine the per-split normalized partials into the final O/LSE.
2533	// The old kernel ran one WARP per (qidx,head) looping serially over splits, so for small
2534	// batch*heads only a few dozen warps were resident -> the cross-split reduce was DRAM-latency
2535	// starved (~40% of decode time, DRAM <2% on hd256). Here:
2536	//   * grid = (total_q*hq, NB): each (qidx,head) is split into NB ~64-elem HDV tiles -> NB x more
2537	//     resident blocks so the strided per-split O loads have enough warps to hide latency.
2538	//   * warp 0 builds the per-split softmax weights in smem (num_splits <= 64).
2539	//   * the split loop is unrolled x4 with 4 independent accumulators -> 4 O loads in flight/thread
2540	//     (memory-level parallelism), the real lever on a latency-bound reduce.
2541	constexpr int COMBINE_THREADS = 128;
2542	constexpr int combine_nb(int hdv) { return hdv / 64 > 0 ? hdv / 64 : 1; }
2543	template <typename TOut, int HDV>
2544	__global__ __launch_bounds__(COMBINE_THREADS) void combine_kernel(
2545	        const float* __restrict__ Opart, const float* __restrict__ LSEpart,
2546	        TOut* __restrict__ O, float* __restrict__ LSE,
2547	        int num_splits, int total_q, int hq, long o_row, long o_head) {
2548	    constexpr int NB = combine_nb(HDV);
2549	    constexpr int TILE = HDV / NB;
2550	    const int witem = blockIdx.x;
2551	    if (witem >= total_q * hq) return;
2552	    const int qidx = witem / hq, head = witem % hq;
2553	    const int tile = blockIdx.y, e0 = tile * TILE;
2554	    const int tid = threadIdx.x;
2555	
2556	    __shared__ float sw[64];          // per-split softmax weight (num_splits <= 64)
2557	    __shared__ float s_inv, s_lse;
2558	    if (tid < 32) {                   // warp 0: lmax -> weights -> denom
2559	        float lmax = -INFINITY;
2560	        for (int s = tid; s < num_splits; s += 32)
2561	            lmax = fmaxf(lmax, LSEpart[((long)s * hq + head) * total_q + qidx]);
2562	#pragma unroll
2563	        for (int o = 16; o > 0; o >>= 1) lmax = fmaxf(lmax, __shfl_xor_sync(0xffffffffu, lmax, o));
2564	        float denom = 0.f;
2565	        for (int s = tid; s < num_splits; s += 32) {
2566	            float lse = LSEpart[((long)s * hq + head) * total_q + qidx];
2567	            float w = (lmax > -INFINITY) ? __expf(lse - lmax) : 0.f;
2568	            sw[s] = w;
2569	            denom += w;
2570	        }
2571	#pragma unroll
2572	        for (int o = 16; o > 0; o >>= 1) denom += __shfl_xor_sync(0xffffffffu, denom, o);
2573	        if (tid == 0) { s_inv = denom > 0.f ? 1.f / denom : 0.f;
2574	                        s_lse = denom > 0.f ? (lmax + __logf(denom)) : -INFINITY; }
2575	    }
2576	    __syncthreads();
2577	    const float inv = s_inv;
2578	    const float* base = Opart + (((long)qidx * hq + head) * HDV);   // + s*sstride + e
2579	    const long sstride = (long)total_q * hq * HDV;
2580	    TOut* o = O + (long)qidx * o_row + (long)head * o_head;
2581	    // A zero-weight split contributes nothing -- but an EMPTY split (num_splits not dividing the
2582	    // key-tile count -> a trailing split starts past the last tile) never writes its Opart slice, so
2583	    // that memory is uninitialized at::empty (clean zeros on a fresh alloc, but NaN/inf when the
2584	    // caching allocator recycles a dirty pool). w==0 must therefore yield exactly 0, NOT 0*Opart
2585	    // (0*NaN=NaN). The select gates the garbage out; non-empty splits always store finite Opart.
2586	    for (int e = e0 + tid; e < e0 + TILE; e += COMBINE_THREADS) {
2587	        float a0 = 0.f, a1 = 0.f, a2 = 0.f, a3 = 0.f;
2588	        int s = 0;
2589	        for (; s + 4 <= num_splits; s += 4) {
2590	            float w0 = sw[s + 0], w1 = sw[s + 1], w2 = sw[s + 2], w3 = sw[s + 3];
2591	            a0 += w0 != 0.f ? w0 * base[(long)(s + 0) * sstride + e] : 0.f;
2592	            a1 += w1 != 0.f ? w1 * base[(long)(s + 1) * sstride + e] : 0.f;
2593	            a2 += w2 != 0.f ? w2 * base[(long)(s + 2) * sstride + e] : 0.f;
2594	            a3 += w3 != 0.f ? w3 * base[(long)(s + 3) * sstride + e] : 0.f;
2595	        }
2596	        float acc = (a0 + a1) + (a2 + a3);
2597	        for (; s < num_splits; ++s) { float w = sw[s]; acc += w != 0.f ? w * base[(long)s * sstride + e] : 0.f; }
2598	        o[e] = from_float<TOut>(acc * inv);
2599	    }
2600	    if (tid == 0 && tile == 0) LSE[(long)head * total_q + qidx] = s_lse;
2601	}
2602	
2603	template <typename TIn, typename TOut, int HD, int HDV, int MAXM>
2604	static void launch_decode_t(const at::Tensor& q, const at::Tensor& k, const at::Tensor& v,
2605	                            at::Tensor& out, at::Tensor& lse, const at::Tensor& cu_q,
2606	                            const std::optional<at::Tensor>& cu_k, const std::optional<at::Tensor>& seqused_k,
2607	                            const std::optional<at::Tensor>& page_table,
2608	                            const std::optional<at::Tensor>& qd, const std::optional<at::Tensor>& kd,
2609	                            const std::optional<at::Tensor>& vd,
2610	                            int b, int hq, int hkv, int total_q, int cfg_splits, double scale,
2611	                            double softcap, int win_l, int win_r, bool causal, int max_klen, cudaStream_t stream) {
2612	    const bool paged = page_table.has_value();
2613	    int rep = hq / hkv;
2614	    long q_row = q.stride(0), q_head = q.stride(1);
2615	    long k_row, k_head, v_row, v_head;
2616	    if (paged) { k_row = k.stride(1); k_head = k.stride(2); v_row = v.stride(1); v_head = v.stride(2); }
2617	    else       { k_row = k.stride(0); k_head = k.stride(1); v_row = v.stride(0); v_head = v.stride(1); }
2618	    long o_row = out.stride(0), o_head = out.stride(1);
2619	    int block_size = paged ? (int)k.size(1) : 0;
2620	    int page_stride = paged ? (int)page_table->stride(0) : 0;
2621	
2622	    // num_splits: forced when cfg>0, else split aggressively for occupancy (this warp path is 1 warp /
2623	    // work-item, so more splits = more resident warps). Don't split finer than 64 keys/split.
2624	    int num_splits;
2625	    if (cfg_splits > 0) num_splits = cfg_splits;
2626	    else {
2627	        int dev = 0; cudaGetDevice(&dev);
2628	        int sms = 132; cudaDeviceGetAttribute(&sms, cudaDevAttrMultiProcessorCount, dev);
2629	        int base = hkv * b;
2630	        int want = (8 * sms * WARPS_PER_BLOCK + base - 1) / (base > 0 ? base : 1);
2631	        int cap = (max_klen + 63) / 64;
2632	        num_splits = std::max(1, std::min(std::min(want, cap), 64));
2633	    }
2634	
