    else if (hd == 96)                DS_DEC(TIN_, TC_, 96, 96, QD_, KD_, VD_);                          \
    else if (hd == 192 && hdv == 128) DS_DEC(TIN_, TC_, 192, 128, QD_, KD_, VD_);                       \
